struct TrivialPOD {
    int a;
    double b;
};

struct NotTrivial {
    int c;
    NotTrivial() = default;
    // User-defined destructor makes type non-trivial
    ~NotTrivial() { /* cleanup */ }
};

// Compile-time checks define the trivial property
static_assert(std::is_trivial_v<int>);
static_assert(std::is_trivial_v<TrivialPOD>);
static_assert(!std::is_trivial_v<NotTrivial>);

// Optimization: Trivial copy uses bitwise copy (e.g., memcpy)
void copy_data(TrivialPOD& dest, const TrivialPOD& src) {
    dest = src; // Highly optimized
}
